/bin/bash -lc "mkdir -p src/util && cat > src/util/ordersApi.mjs <<'EOF'
/**
 * Normalize the backend's order-list response (the payload loaded by
 * src/pages/other/RecentOrder.js) into a small, predictable shape:
 *
 *   { orders, pages, total, onThisPage }
 *
 * - orders:     list of orders          (response.orders)
 * - pages:      number of pages         (response.totalPages)
 * - total:      total number of records (response.recordsTotal)
 * - onThisPage: records on this page    (response.recordsOnThisPage)
 *
 * Missing or invalid values become an empty list or 0.
 */

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

export function normalizeOrderList(response) {
  const body = response && typeof response === \"object\" ? response : {};

  return {
    orders: Array.isArray(body.orders) ? body.orders : [],
    pages: toNumber(body.totalPages),
    total: toNumber(body.recordsTotal),
    onThisPage: toNumber(body.recordsOnThisPage),
  };
}
EOF
